export const MTS_RDM_REAL_STUDENTS: Student[] = RAW_MTS_STUDENTS.map((row, idx) => {
  const seq = String(row.no).padStart(3, '0');
  const lowerCode = row.kelasCode.toLowerCase();
  return {
    id: `std-mts-${lowerCode}-${seq}`,
    nomorPeserta: `26-MTS-${row.kelasCode}-${seq}`,
    nisn: row.nisn,
    nama: row.nama,
    jenjang: 'MTs',
    kelas: row.kelas,
    tempatLahir: row.tempatLahir,
    tanggalLahir: row.tanggalLahir,
    ruang: row.ruang,
    sesi: row.sesi,
    pin: buildPinFromNisn(row.nisn, idx + 1),
    gender: row.gender,
    statusAktif: true,
  };
});
